contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry that may send Ether
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // read owner before
        address ownerBefore = c.owner();

        // call go forwarding amount
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner after
        address ownerAfter = c.owner();

        // General invariant: owner is never changed to this contract's address
        // and thus ownerAfter != address(this). Also ownerAfter equals ownerBefore
        // (i.e., owner doesn't become the test contract and remains the deployer)
        assert(ownerAfter == ownerBefore && ownerAfter != address(this));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary amount to forward to c.go. This function is payable so the
    // test caller can fund this contract before calling run.
    function run(uint amount) public payable {
        // If we intend to send Ether to c, ensure this contract has it available.
        require(address(this).balance >= amount);

        // Record balances before the call
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;
        address ownerBefore = c.owner();

        // Call c.go sending `amount` wei. Must be a top-level state-changing call.
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after the call
        uint afterTestBalance = address(this).balance;
        uint afterCBalance = address(c).balance;
        address ownerAfter = c.owner();

        // General invariant to assert for all inputs: this contract's balance did not increase
        // as a result of calling c.go (i.e., c never transfers Ether to the caller; it sends
        // any remaining funds to owner). We allow the balance to decrease by at most `amount`.
        // Also assert owner remains unchanged and c's balance is <= beforeCBalance + amount.
        assert(
            afterTestBalance <= beforeTestBalance &&
            ownerAfter == ownerBefore &&
            afterCBalance <= beforeCBalance + amount
        );
    }

    // receive to allow this contract to accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address public deployerOwner;

    constructor(C _c) { c = _c; deployerOwner = c.owner(); }

    // sendAmount is the Ether forwarded to c.go
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to send");

        // record caller (this contract) balance before calling c.go
        uint before = address(this).balance;

        bool reverted;
        try c.go{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(this).balance;

        // General rule: calling c.go cannot make this contract lose Ether beyond the amount it intentionally sent (sendAmount).
n        // Since sendAmount was deducted when sending value, after >= before - sendAmount.
        // Also owner stored in c remains equal to the deployerOwner.
        assert(after + sendAmount >= before && c.owner() == deployerOwner);
    }

    receive() external payable {}
}

