    // Single public entry that drives c and asserts a general invariant
    function run(uint amount) public payable {
        // If we will send Ether to c, ensure this contract holds it first
        require(address(this).balance >= amount);

        // Record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        address beforeOwner = c.owner();

        // Make the state-changing call on c, sending 'amount' wei
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        address afterOwner = c.owner();

        // General rule asserted for all inputs: owner never changes, run reaches this point (so no self-destruct/revert of this transaction),
