    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Read observable before-values
        address ownerBefore = c.owner();
        uint256 testBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call c.go forwarding 'amount' wei
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        address ownerAfter = c.owner();
        uint256 testBalanceAfter = address(this).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule asserted:
        // - owner is unchanged
        // - c holds no more Ether than before (address(c).balance_after <= address(c).balance_before)
        // - the test contract's balance did NOT increase as a result of calling c.go (it may decrease by `amount` sent;
        //   but it should never gain Ether transferred from C during c.go)
        // This covers the intended safety property that c.go does not send Ether to callers.
        assert(
            ownerBefore == ownerAfter
            && contractBalanceAfter <= contractBalanceBefore
            && testBalanceAfter <= testBalanceBefore
        );
    }

    // allow receiving Ether if target forwards to this contract in some hypothetical variant
    receive() external payable {}
